ng;\n  rules: string[]; workflows: string[]; deliverables: string[];\n  success_metrics: string[]; memory_policy: string;\n  tools_required: string[]; runtime_targets: string[];\n  risk_profile: { level: string; injection_score: number; overlap_score: number; flags: string[] };\n  evaluation_status: 'pending' | 'passed' | 'rejected';\n  activation_status: 'draft' | 'active' | 'rejected' | 'deactivated';\n}\n\nexport interface Evaluation {\n  profile_id: string; schema_valid: boolean; schema_errors: string[];\n  injection_score: number; injection_flags: string[];\n  overlap_score: number; overlap_with: string | null; overlaps: { id: string; score: number }[];\n  risk_level: string; flags: string[]; status: 'pending' | 'passed' | 'rejected';\n  score?: number;\n}\n\nexport class CatalogDB {\n  private db: Database.Database;\n  constructor(path = ':memory:') {\n    this.db = new Database(path); this.db.exec(MIGRATION);\n    if (!(this.db.prepare('PRAGMA table_info(evaluations)').all() as Array<{name:string}>).some(column => column.name === 'score')) this.db.exec('ALTER TABLE evaluations ADD COLUMN score REAL');\n  }\n  close() { this.db.close(); }\n  transaction<T>(operation: () => T): T { return this.db.transaction(operation)(); }\n\n  private invalidateActivation(profileId: string, reason: string) {\n    const changed = this.db.prepare(\"UPDATE activations SET status='deactivated', deactivated_at=? WHERE profile_id=? AND status='active'\").run(new Date().toISOString(), profileId);\n    if (changed.changes) this.audit(profileId, 'activation_invalidated', JSON.stringify({reason}));\n  }\n\n  upsertProfile(p: Profile) {\n    this.transaction(() => {\n    const prior = this.getProfile(p.id);\n    this.db.prepare(\n      `INSERT INTO profiles(id,name,division,source_repo,source_path,version_hash,document)\n       VALUES(?,?,?,?,?,?,?)\n       ON CONFLICT(id) DO UPDATE SET name=excluded.name, division=excluded.division,\n         source_repo=excluded.source_repo, source_path=excluded.source_path,\n         version_hash=excluded.version_hash, document=excluded.document`\n    ).run(p.id, p.name, p.division, p.source_repo, p.source_path, p.version_hash, JSON.stringify(p));\n    if (prior && prior.version_hash !== p.version_hash) this.invalidateActivation(p.id, 'profile_version_changed');\n    });\n  }\n  getProfile(id: string): Profile | null {\n    const row: any = this.db.prepare('SELECT document FROM profiles WHERE id=?').get(id);\n    return row ? JSON.parse(row.document) : null;\n  }\n  listProfiles(): Profile[] {\n    return (this.db.prepare('SELECT document FROM profiles ORDER BY name').all() as any[])\n      .map(r => JSON.parse(r.document));\n  }\n  setEvaluation(ev: Evaluation, versionHash: string) {\n    this.transaction(() => {\n    const id = `${ev.profile_id}:${versionHash}`;\n    this.db.prepare(\n      `INSERT INTO evaluations(id,profile_id,version_hash,status,schema_valid,overlap_score,injection_score,risk_level,flags,score)\n       VALUES(?,?,?,?,?,?,?,?,?,?)\n       ON CONFLICT(id) DO UPDATE SET status=excluded.status, schema_valid=excluded.schema_valid,\n         overlap_score=excluded.overlap_score, injection_score=excluded.injection_score,\n         risk_level=excluded.risk_level, flags=excluded.flags, score=excluded.score`\n    ).run(id, ev.profile_id, versionHash, ev.status, ev.schema_valid ? 1 : 0, ev.overlap_score, ev.injection_score, ev.risk_level, JSON.stringify(ev.flags), ev.score ?? null);\n    if (ev.status !== 'passed' && this.getProfile(ev.profile_id)?.version_hash === versionHash) this.invalidateActivation(ev.profile_id, 'evaluation_not_passed');\n    });\n  }\n  getEvaluation(profileId: string): any {\n    const row: any = this.db.prepare(`SELECT * FROM evaluations WHERE profile_id=?\n      ORDER BY (version_hash = (SELECT version_hash FROM profiles WHERE id=?)) DESC, rowid DESC LIMIT 1`).get(profileId, profileId);\n    if (!row) return null;\n    return { ...row, flags: JSON.parse(row.flags), schema_valid: !!row.schema_valid };\n  }\n  setActivation(profileId: string, status: string, target: string | null, artifact: string | null) {\n    const now = new Date().toISOString();\n    if (status === 'active') {\n      this.db.prepare(\n        `INSERT INTO activations(profile_id,status,target,compiled_artifact,activated_at) VALUES(?,?,?,?,?)\n         ON CONFLICT(profile_id) DO UPDATE SET status=excluded.status, target=excluded.target,\n           compiled_artifact=excluded.compiled_artifact, activated_at=excluded.activated_at, deactivated_at=NULL`\n      ).run(profileId, status, target, artifact, now);\n    } else {\n      this.db.prepare(\n        `INSERT INTO activations(profile_id,status) VALUES(?,?)\n         ON CONFLICT(profile_id) DO UPDATE SET status=excluded.status, deactivated_at=?`\n      ).run(profileId, status, now);\n    }\n  }\n  getActivation(profileId: string): any {\n    return this.db.prepare('SELECT * FROM activations WHERE profile_id=?').get(profileId) || null;\n  }\n  audit(profileId: string, action: string, detail: string) {\n    this.db.prepare('INSERT INTO audit_ledger(profile_id,action,detail) VALUES(?,?,?)').run(profileId, action, detail);\n  }\n  setOverlap(a: string, b: string, score: number) {\n    const [x, y] = a < b ? [a, b] : [b, a];\n    this.db.prepare('INSERT OR REPLACE INTO overlaps(a,b,score) VALUES(?,?,?)').run(x, y, score);\n  }\n  replaceOverlaps(profileId: string, overlaps: Array<{ id: string; score: number }>) {\nimport type { Profile } from './db';\n\nexport type Target = 'openclaw' | 'codex' | 'claude-code' | 'cursor' | 'gemini-cli' | 'djimit-native';\nexport const TARGETS: Target[] = ['openclaw', 'codex', 'claude-code', 'cursor', 'gemini-cli', 'djimit-native'];\nexport interface CompiledArtifact { target: Target; files: Record<string, string>; stub?: boolean }\n\nfunction clamp(s?: string): string { return String(s ?? '').trim(); }\n\nexport function compile(profile: Profile, target: Target): CompiledArtifact {\n  switch (target) {\n    case 'openclaw': return compileOpenClaw(profile);\n    case 'codex': return compileCodex(profile);\n    case 'claude-code': return { target, files: { [`${profile.id}.md`]: stub(profile, 'Claude Code .md agent') }, stub: true };\n    case 'cursor': return { target, files: { [`${profile.id}.mdc`]: stub(profile, 'Cursor .mdc rule') }, stub: true };\n    case 'gemini-cli': return { target, files: { 'SKILL.md': stub(profile, 'Gemini CLI SKILL.md') }, stub: true };\n    case 'djimit-native': return { target, files: { 'djimit-agent.yaml': `id: ${profile.id}\\nname: ${profile.name}\\ndivision: ${profile.division}\\nmission: ${JSON.stringify(profile.mission)}\\nruntime_targets: [${profile.runtime_targets.join(', ')}]\\n` } };\n  }\n}\n\nfunction compileOpenClaw(p: Profile): CompiledArtifact {\n  const soul = `# SOUL — ${p.name}\\n\\n${clamp(p.persona) || 'Persona not specified.'}\\n\\n## Mission\\n${clamp(p.mission)}\\n`;\n  const agents = [\n    `# AGENTS — ${p.name}`, '', `Division: ${p.division}`, `Source: ${p.source_repo}/${p.source_path}`, '',\n    '## Mission', clamp(p.mission), '',\n    '## Critical Rules', ...(p.rules.length ? p.rules.map(r => `- ${r}`) : ['- (none)']), '',\n    '## Workflow', ...(p.workflows.length ? p.workflows.map(w => `- ${w}`) : ['- (none)']), '',\n    '## Deliverables', ...(p.deliverables.length ? p.deliverables.map(d => `- ${d}`) : ['- (none)']), '',\n    '## Success Metrics', ...(p.success_metrics.length ? p.success_metrics.map(m => `- ${m}`) : ['- (none)']), '',\n    '## Memory Policy', clamp(p.memory_policy) || '(default — retain task-relevant context only)', '',\n    '## Tools Required', ...(p.tools_required.length ? p.tools_required.map(t => `- ${t}`) : ['- (none)']), '',\n  ].join('\\n');\n  const identity = `# IDENTITY — ${p.name}\\n\\nid: ${p.id}\\nname: ${p.name}\\ndivision: ${p.division}\\nruntime_targets: ${p.runtime_targets.join(', ') || '(none)'}\\n`;\n  return { target: 'openclaw', files: { 'SOUL.md': soul, 'AGENTS.md': agents, 'IDENTITY.md': identity } };\n}\n\nfunction compileCodex(p: Profile): CompiledArtifact {\n  const instructions = [\n    `You are ${p.name} (${p.division}).`,\n    clamp(p.persona) && `Persona: ${p.persona}`,\n    `Mission: ${clamp(p.mission)}`,\n    p.rules.length && `Rules:\\n${p.rules.map(r => `- ${r}`).join('\\n')}`,\n    p.workflows.length && `Workflow:\\n${p.workflows.map(w => `- ${w}`).join('\\n')}`,\n    p.tools_required.length && `Tools: ${p.tools_required.join(', ')}`,\n  ].filter(Boolean).join('\\n\\n');\n  return { target: 'codex', files: { 'agent.toml': `[agent]\\nname = ${JSON.stringify(p.name)}\\nmodel = \"gpt-4o\"\\ninstructions = ${JSON.stringify(instructions)}\\n` } };\n}\n\nfunction stub(p: Profile, label: string): string { return `# ${p.name} — ${label} (F5 stub, not implemented)\\n\\nMission: ${p.mission}\\n`; }\nimport { createHash } from 'node:crypto';\nimport { toList, firstParagraph, type ParsedAgent } from './parser';\nimport type { Profile } from './db';\n\nfunction firstNonEmpty(...vals: any[]): string {\n  for (const v of vals) if (v && String(v).trim()) return String(v).trim();\n  return '';\n}\nfunction listOrSplit(val: any, text?: string): string[] {\n  if (Array.isArray(val)) return val.map(String);\n  if (text) return toList(text);\n  return [];\n}\nfunction divisionFromPath(sourcePath: string): string {\n  const parts = String(sourcePath || '').split('/').filter(Boolean);\n  return parts[0] || 'unknown';\n}\nfunction slug(s: string): string {\n  return String(s || '').toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g, '')\n    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');\n}\n\nexport function hashProfile(profile: Profile): string {\n  const stable = JSON.stringify(profile, Object.keys(profile).sort());\n  return createHash('sha256').update(stable).digest('hex').slice(0, 16);\n}\n\nexport function normalizeAgent(parsed: ParsedAgent): Profile {\n  const { frontmatter: fm, sections: s, preamble, sourceRepo, sourcePath } = parsed;\n  const name = firstNonEmpty(fm.name, fm.title);\n  const division = firstNonEmpty(fm.division, divisionFromPath(sourcePath));\n  const id = slug(`${division}/${name}`) || `agent/${Math.random().toString(36).slice(2, 8)}`;\n  const persona = firstNonEmpty(fm.vibe && `${fm.vibe}`, preamble && firstParagraph(preamble), s.memory_policy && firstParagraph(s.memory_policy), fm.description);\n\n  const profile: Profile = {\n    id, name, division,\n    description: firstNonEmpty(fm.description, ''),\n    source_repo: sourceRepo || '', source_path: sourcePath || '',\n    version_hash: '',\n    persona,\n    mission: firstNonEmpty(s.mission && firstParagraph(s.mission), fm.description, ''),\n    rules: listOrSplit(fm.rules, s.rules),\n    workflows: listOrSplit(fm.workflows, s.workflows),\n    deliverables: listOrSplit(fm.deliverables, s.deliverables),\n    success_metrics: listOrSplit(fm.success_metrics, s.success_metrics),\n    memory_policy: firstNonEmpty(s.memory_policy && firstParagraph(s.memory_policy), ''),\n    tools_required: listOrSplit(fm.tools_required, s.tools_required),\n    runtime_targets: Array.isArray(fm.runtime_targets) ? fm.runtime_targets.map(String) : [],\n    risk_profile: { level: 'low', injection_score: 0, overlap_score: 0, flags: [] },\n    evaluation_status: 'pending', activation_status: 'draft',\n  };\n  profile.version_hash = hashProfile(profile);\n  return profile;\n}\n","exit_code":0,"status":"completed"}}
