import { AgentCatalog, parseAgentMarkdown, normalizeAgent, runStaticGate, validateSchema, scanInjection, overlapScore, compile } from '../src';

const FIX = (f: string) => readFileSync(join(process.cwd(), 'fixtures/agents', f), 'utf8');

describe('parser', () => {
